    /// <summary>
    /// Finds the specified record in the <c>METBusinessUnit</c> table.
    /// </summary>
    /// <param name="_businessName">
    /// The BusinessName of the <c>METBusinessUnit</c> record to find.
    /// </param>
    /// <param name="_statePrefix">
    /// The StatePrefix of the <c>METBusinessUnit</c> record to find.
    /// </param>
    /// <param name="_forupdate">
    /// A Boolean value that indicates whether to read the record for update; optional.
    /// </param>
    /// <param name="_concurrencyModel">
    /// The ConcurrencyModel value set to; Auto.
    /// </param>
    /// <returns>
    /// A record in the <c>METBusinessUnit</c> table; otherwise, an empty record.
    /// </returns>
    public static METBusinessUnit find(
        METBusinessName _businessName,
        int _statePrefix,
        boolean _forupdate = false,
        ConcurrencyModel _concurrencyModel = ConcurrencyModel::Auto)
    {
        METBusinessUnit businessUnit;

        businessUnit.selectForUpdate(_forupdate);
        if (_forupdate && _concurrencyModel != ConcurrencyModel::Auto)
        {
            businessUnit.concurrencyModel(_concurrencyModel);
        }

        select firstonly businessUnit 
            where businessUnit.BusinessName == _businessName
            && businessUnit.StatePrefix == _statePrefix;

        return businessUnit;
    }

    /// <summary>
    /// Exists the specified record in the <c>METBusinessUnit</c> table.
    /// </summary>
    /// <param name = "_businessName">
    /// The BusinessName of the <c>METBusinessUnit</c> record to exists.
    /// </param>
    /// <returns>A Boolean value that indicates whether the record exists or not</returns>
    public static boolean exist(METBusinessName _businessName)
    {
        boolean found;

        found = (select firstonly RecId from METBusinessUnit
                    where METBusinessUnit.BusinessName == _businessName).RecId != 0;

        return found;
    }

/// <summary>
/// Decides whether the value of a specific field is valid.
/// </summary>
/// <param name="_fieldName">
/// The specified name of field to validate.
/// </param>
/// <param name="_arrayIndex">
/// THe specified array index for the field; optional.
/// </param>
/// <returns>
/// true if the validation passes; otherwise, false.
/// </returns>
/// <remarks>
/// Validates the <c>BusinessPrefix</c> field.  Returns true if the field contains only digits; otherwise, displays an error message and returns false.
/// </remarks>
public boolean validateFieldValue(FieldName _fieldName, int _arrayIndex = 1)
{
    boolean ret;

    ret = super(_fieldName, _arrayIndex);
    
    if (ret)
    {
        switch (_fieldName)
        {
            case fieldStr(METBusinessUnit,BusinessPrefix ) :
                if (strlen(int2str(this.BusinessPrefix)) > 1)
                {
                    ret = checkFailed("@MET:METBusinessPrefixCheck");
                }
                break;
        }
    }

    return ret;
}

   /// <summary>
   /// lookup for Business unit
   /// </summary>
   /// <param name = "_formReferenceControl">formReferenceControl</param>
   /// <returns>Business unit</returns>
   public static Common lookupReferenceType(FormReferenceControl _formReferenceControl)
   {
       SysReferenceTableLookup sysRefTableLookup;
       Query                   lookupQuery = new Query();
       QueryBuildDataSource    lookupQueryDataSource;
        
       sysRefTableLookup = SysReferenceTableLookup::newParameters(tableNum(METBusinessUnit), _formReferenceControl);
    
       sysRefTableLookup.addLookupfield(fieldNum(METBusinessUnit, BusinessName));
       sysRefTableLookup.addLookupfield(fieldNum(METBusinessUnit, BusinessPrefix));
       sysRefTableLookup.addLookupfield(fieldNum(METBusinessUnit, StatePrefix));
        
       lookupQueryDataSource = lookupQuery.addDataSource(tableNum(METBusinessUnit));
        
       sysRefTableLookup.parmQuery(lookupQuery);

       return sysRefTableLookup.performFormLookup();
   }

    /// <summary>
    /// Finds the specified record in the <c>METBusinessUnit</c> table.
    /// </summary>
    /// <param name = "_recId">RecId</param>
    /// <param name = "_forUpdate">A Boolean value </param>
    /// <returns>A record in the <c>METBusinessUnit</c> table; otherwise, an empty record.</returns>
    public static METBusinessUnit findRecId(RecId    _recId,
                               boolean  _forUpdate = false)
    {
        METBusinessUnit metBusinessUnit;

        if (_recId)
        {
            metBusinessUnit.selectForUpdate(_forUpdate);

            select firstonly metBusinessUnit
                where metBusinessUnit.RecId == _recId;
        }

        return metBusinessUnit;
    }

    /// <summary>
    /// validate entered values
    /// </summary>
    /// <returns>boolean</returns>
    public boolean validateWrite()
    {
        boolean ret;
    
        ret = super();

        if(this.EnableStatePrefix && !this.StatePrefix)
        {
            ret = checkFailed("@MET:METStatePrefixCheckEntered");
        }
    
        return ret;
    }

/// <summary>
/// lookup for Business unit
/// </summary>
/// <param name = "_formInt64Control">FormInt64Control</param>
public static void businesUnitLookup(FormInt64Control _formInt64Control)
{
    SysTableLookup          sysTableLookup;
    Query                   lookupQuery = new Query();
    QueryBuildDataSource    lookupQueryDataSource;
     
    sysTableLookup = SysTableLookup::newParameters(tableNum(METBusinessUnit), _formInt64Control);
    sysTableLookup.addLookupfield(fieldNum(METBusinessUnit, BusinessName));
    sysTableLookup.addLookupfield(fieldNum(METBusinessUnit, BusinessPrefix));
    sysTableLookup.addLookupfield(fieldNum(METBusinessUnit, StatePrefix));
    sysTableLookup.addLookupfield(fieldNum(METBusinessUnit, RecId), true);
    lookupQueryDataSource = lookupQuery.addDataSource(tableNum(METBusinessUnit));
    sysTableLookup.parmQuery(lookupQuery);
    sysTableLookup.performFormLookup();
}
